import sys, json, os
sys.path.insert(0, "tools")
import layout_metrics as lm
st = json.load(open("analysis/layout_stats.json"))
rows = []; cnt = {}
for i in range(1, 11):
    s = "s%02d" % i
    g = lm.metrics(*lm.pptx_slide_els("out/audit/%s.pptx" % s)); o = lm.metrics(*lm.orig_by_id(s))
    d = lm.distance(g, o)
    top = sorted(d["normalized"], key=lambda k: -d["normalized"][k])[:3]
    for k in top: cnt[k] = cnt.get(k, 0) + 1
    rows.append((s, d["structure_distance"], [(k, g[k], o[k]) for k in top]))
L = ["# Structure report: audit rebuilds vs archive originals", "",
     "Generated by tools/layout_metrics.py (distance: weighted mean of min(1,|delta|/scale); see DIST in the module). 0 = same structure.",
     "Per slide: the 3 metrics with the largest normalized delta, shown as gen vs orig. Archive p10/p50/p90 in analysis/layout_stats.json.", "",
     "| slide | distance | biggest delta 1 | 2 | 3 |", "|---|---|---|---|---|"]
for s, d, t in rows:
    L.append("| %s | %.3f | " % (s, d) + " | ".join("%s: %s vs %s" % x for x in t) + " |")
L += ["", "Metrics most often among the top 3: " + ", ".join("%s (%d)" % kv for kv in sorted(cnt.items(), key=lambda kv: -kv[1])), "",
      "Caveats: PDF original s03 uses PyMuPDF blocks (no group flattening, text blocks not shapes); n_boxes/x_starts are inflated for originals with many decorative pieces."]
open("analysis/ai_audit/structure_report.md", "w", encoding="utf8").write("\n".join(L) + "\n")
print("\n".join(L))
